230:     private static void Blank(StringBuilder result, char c) => result.Append(c == '\n' ? '\n' : ' ');
231: 
232:     private static bool IsQuoteRun(string source, int index, int count)
233:     {
234:         for (var q = 0; q < count; q++)
235:         {
236:             if (index + q >= source.Length || source[index + q] != '"')
237:                 return false;
238:         }
239: 
240:         return true;
241:     }
